	newInt := decimal.NewFromInt(mv)
	newVal := newInt.Add(frac)
	if sign < 0 {
		newVal = newVal.Neg()
	}
	// Ensure scale exactly `scale` by truncating/padding? Keep as is but quantize to scale
	// Use Truncate to scale to avoid introducing extra digits
	newVal = newVal.Truncate(scale)
	return newVal
}

func pow10(n int) int64 {
